# Log 05: exhaustive check over all 2^17 assignments allowed by the proved relations.
# Usage: python3 code_sel2_exhaustive_2pow17.py [N]   (N = how many assignments to check; default all, ~40 s).
# Needs code_sel2_symbolic_model.py and code_sel2_rho.py in the same folder.
import sys,time,collections,os
sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)))
from code_sel2_symbolic_model import *

piv=solve_space(rels,NV)
free=[i for i in range(NV) if i not in piv]
gens=['-1','2']+L; n=len(gens)

# precompute annihilators of the local images
ann={}
for v in L:
    l=lab[v]
    if l=='P': Bs=span_basis([[0,1,0,1],[0,0,0,1] if m4(v)==3 else [1,0,1,0]])
    elif l=='Q': Bs=span_basis([[0,1,0,0],[0,0,0,1] if m4(v)==3 else [1,0,0,0]])
    else: Bs=span_basis([[0,0,1,0],[0,0,0,1]])
    ann[v]=annihilator(Bs,4)
ann2=annihilator(local2(),6); annI=annihilator([[0,1]],2)

def addc(rows,ann,cd,cf):
    for h in ann:
        row=[0]*(2*n)
        for gi,g in enumerate(gens):
            ca=cf(g)
            for t in range(cd):
                if h[t] and ca[t]: row[gi]^=1
                if h[cd+t] and ca[t]: row[n+gi]^=1
        rows.append(row)

rows=[]
addc(rows,ann2,3,cls2_gen); addc(rows,annI,1,lambda g:[1 if g=='-1' else 0])
fixed=[int(''.join(map(str,r)),2) for r in rows]

def dim(bits):
    rs=list(fixed)
    for v in L:
        rr=[]
        addc(rr,ann[v],2,lambda g,v=v: cls_gen(g,v,bits))
        rs+= [int(''.join(map(str,r)),2) for r in rr]
    basis=[];rk=0
    for r in rs:
        for b in basis: r=min(r,r^b)
        if r: basis.append(r);rk+=1
    return 2*n-rk

def bits_from(k):
    x=0
    for t,i in enumerate(free):
        if k>>t&1: x|=1<<i
    for p,(m,c) in piv.items():
        rest=m&~(1<<p)
        if (bin(rest&x).count('1')&1)^c: x|=1<<p
    return x

N=1<<len(free)
lim=int(sys.argv[1]) if len(sys.argv)>1 else N
t0=time.time(); cnt=collections.Counter()
for k in range(lim):
    b=bits_from(k); cnt[(B_of(b),dim(b))]+=1   # key: (B bit: 0 means B=+1, dim Sel2)
print("space",N,"checked",lim,"time",time.time()-t0); print(cnt)
# expected for the full run: {(0, 4): 65536, (1, 2): 65536}

# Log 05: symbolic model of the 24x24 Sel2 matrix on the factor shape, plus the proved relations.
# Needs code_sel2_rho.py in the same folder. Needs: sympy.
import itertools, random
from sympy import legendre_symbol as ls
from code_sel2_rho import span_basis, annihilator, rank_f2, local_image_2, cls_2, PQ_from_u
from fractions import Fraction

L=['3','d','e','f','7','41','p1','p2','q1','q2']
r8={'3':3,'d':3,'e':5,'f':7,'7':7,'41':1,'p1':1,'p2':1,'q1':7,'q2':7}
lab={'3':'D','d':'D','e':'D','f':'D','7':'P','p1':'P','p2':'P','41':'Q','q1':'Q','q2':'Q'}
m4=lambda x: r8[x]%4
idx={x:i for i,x in enumerate(L)}
pairs=[(x,y) for i,x in enumerate(L) for y in L[i+1:]]
pid={pr:i for i,pr in enumerate(pairs)}   # 45 variables
NV=len(pairs)

def chi_expr(x,y):
    """affine expr (mask,const) for the chi bit of (x/y), x!=y"""
    if idx[x]<idx[y]: return (1<<pid[(x,y)],0)
    c=1 if (m4(x)==3 and m4(y)==3) else 0
    return (1<<pid[(y,x)],c)

def add(*es):
    m=0;c=0
    for a,b in es: m^=a;c^=b
    return (m,c)
def const(c): return (0,c)

# ---------- proved relations (each affine expr must equal 0) ----------
rels=[]
def eq(e,val): rels.append(add(e,const(val)))        # e == val
def eqsum(es,val): rels.append(add(*es,const(val)))  # sum(es) == val

# x mod 3 facts
for x,v in [('p1',1),('d',1),('e',1),('f',0),('7',0),('41',1)]: eq(chi_expr(x,'3'),v)
eq(chi_expr('p2','3'),0)
eqsum([chi_expr('q1','3'),chi_expr('q2','3')],0)
# y=7
for x,v in [('d',0),('e',1),('f',1),('3',1),('41',1)]: eq(chi_expr(x,'7'),v)
eqsum([chi_expr('q1','7'),chi_expr('q2','7')],0)
# y=41
for x,v in [('d',1),('e',0),('f',1),('3',1),('7',1)]: eq(chi_expr(x,'41'),v)
eqsum([chi_expr('p1','41'),chi_expr('p2','41')],1)
# d,e,f
eq(chi_expr('e','d'),0); eq(chi_expr('f','d'),0); eq(chi_expr('e','f'),1)
# 3,7,41 vs d,e,f
for (x,y),v in {('3','d'):0,('3','e'):1,('3','f'):1,('7','d'):1,('7','e'):1,('7','f'):0,('41','d'):1,('41','e'):0,('41','f'):1}.items(): eq(chi_expr(x,y),v)
# p relations (36-09FB identities)
for y in 'def': eqsum([chi_expr('p1',y),chi_expr('p2',y)],0)
for p in ('p1','p2'): eqsum([chi_expr(p,'f'),chi_expr(p,'d'),chi_expr(p,'e')],0)
# q relations (not needed for the dichotomy, see log 05)
eqsum([chi_expr('q1','d'),chi_expr('q2','d')],1)
eqsum([chi_expr('q1','e'),chi_expr('q2','e')],1)
eqsum([chi_expr('q1','f'),chi_expr('q2','f')],0)
for q in ('q1','q2'): eqsum([chi_expr(q,'d'),chi_expr(q,'e'),chi_expr(q,'f')],1)

def solve_space(rels,nv):
    piv={}
    for m,c in rels:
        for p,(pm,pc) in piv.items():
            if m>>p&1: m^=pm;c^=pc
        if m==0:
            if c: return None
            continue
        p=m.bit_length()-1
        for q,(qm,qc) in list(piv.items()):
            if qm>>p&1: piv[q]=(qm^m,qc^c)
        piv[p]=(m,c)
    return piv

def sample(piv,rng,fixed=None):
    free=[i for i in range(NV) if i not in piv]
    x=0
    for i in free:
        if rng.random()<.5: x|=1<<i
    for p,(m,c) in piv.items():
        rest=m&~(1<<p)
        par=bin(rest&x).count('1')&1
        if par^c: x|=1<<p
    return x,free

def chi(x,y,bits):
    m,c=chi_expr(x,y); return (bin(m&bits).count('1')&1)^c

B2=None
def local2():
    global B2
    if B2 is None:
        P,Q=PQ_from_u(35456387); B2=local_image_2(P,Q)   # dyadic image is the same along the progression
    return B2

def cls_gen(g,v,bits):
    """class of generator g in Q_v*/sq for odd support prime v (names)."""
    if g=='-1': return [0, 1 if m4(v)==3 else 0]
    if g=='2': return [0, 1 if r8[v] in (3,5) else 0]
    if g==v: return [1,0]
    return [0, chi(g,v,bits)]

def cls2_gen(g):
    if g=='-1': return [0,1,0]
    if g=='2': return [1,0,0]
    u=r8[g]; return [0,1 if u%4==3 else 0, 1 if u in (3,5) else 0]

def matrix(bits):
    gens=['-1','2']+L; n=len(gens); rows=[]
    def addc(ann,cd,cf):
        for h in ann:
            row=[0]*(2*n)
            for gi,g in enumerate(gens):
                ca=cf(g)
                for t in range(cd):
                    if h[t] and ca[t]: row[gi]^=1
                    if h[cd+t] and ca[t]: row[n+gi]^=1
            rows.append(row)
    for v in L:
        l=lab[v]
        if l=='P': Bs=span_basis([[0,1,0,1],[0,0,0,1] if m4(v)==3 else [1,0,1,0]])
        elif l=='Q': Bs=span_basis([[0,1,0,0],[0,0,0,1] if m4(v)==3 else [1,0,0,0]])
        else: Bs=span_basis([[0,0,1,0],[0,0,0,1]])
        addc(annihilator(Bs,4),2,lambda g,v=v: cls_gen(g,v,bits))
    addc(annihilator(local2(),6),3,cls2_gen)
    addc(annihilator([[0,1]],2),1,lambda g:[1 if g=='-1' else 0])
    return rows,gens

def sel2dim(bits):
    rows,gens=matrix(bits); return 2*len(gens)-rank_f2(rows)

def B_of(bits): return chi('p1','e',bits)   # 0 => B=+1, 1 => B=-1
